#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("logi.txt");
    string ip, czas;
    map<string, int> cnt;
    int total = 0;
    while (plik >> ip >> czas) {
        cnt[ip]++;
        total++;
    }
    vector<pair<int, string>> ranking;
    for (auto& p : cnt) ranking.push_back({p.second, p.first});
    sort(ranking.begin(), ranking.end(), [](auto& a, auto& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    cout << "Ranking adresow IP:" << endl;
    for (int i = 0; i < (int)ranking.size(); i++) {
        cout << i+1 << ". " << ranking[i].second << ": " << ranking[i].first << endl;
    }
    cout << "Unikalne adresy: " << cnt.size() << endl;
    cout << "Lacznie wpisow: " << total << endl;
    return 0;
}
```

